const setPlatformIntent = `-- name: SetPlatformIntent :one
UPDATE network_platform_resources SET state=$1,reason='',last_operation_id=$2,version=version+1,updated_at=clock_timestamp()
WHERE cluster_id=$3 AND resource_id=$4 AND version=$5 RETURNING resource_id, kind, cluster_id, name, description, state, reason, version, created_at, updated_at, observed_at, last_operation_id, provider_name, provider_uid, provider_images, binding_id, pending_action, pending_since
`

type SetPlatformIntentParams struct {
	State       string
	OperationID string
	ClusterID   string
	ResourceID  string
	Version     int64
}

func (q *Queries) SetPlatformIntent(ctx context.Context, arg SetPlatformIntentParams) (NetworkPlatformResource, error) {
	row := q.db.QueryRow(ctx, setPlatformIntent,
		arg.State,
		arg.OperationID,
		arg.ClusterID,
		arg.ResourceID,
		arg.Version,
	)
	var i NetworkPlatformResource
	err := row.Scan(
		&i.ResourceID,
		&i.Kind,
		&i.ClusterID,
		&i.Name,
		&i.Description,
		&i.State,
		&i.Reason,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ObservedAt,
		&i.LastOperationID,
		&i.ProviderName,
		&i.ProviderUid,
		&i.ProviderImages,
		&i.BindingID,
		&i.PendingAction,
		&i.PendingSince,
	)
	return i, err
}

